const lead = $('Normalize Lead').first().json;

const leadId =
  'L-' +
  Date.now().toString(36).toUpperCase() +
  Math.random().toString(36).slice(2, 5).toUpperCase();

return [{
  json: {
    lead_id: leadId,
    created_at: new Date().toISOString(),
    name: lead.name,
    email: lead.email,
    phone: lead.phone,
    company: lead.company,
    service_interest: lead.service_interest,
    budget: lead.budget,
    timeline: lead.timeline,
    message: lead.message,
    source: lead.source,
    status: 'new',
    last_seen_at: new Date().toISOString(),
    duplicate_count: 0
  }
}];

// ===== Config (পরে এখানেই tune করবেন) =====
const FREE_DOMAINS = [
  'gmail.com', 'yahoo.com', 'hotmail.com', 'outlook.com',
  'icloud.com', 'live.com', 'proton.me', 'protonmail.com'
];
const HOT_MIN = 65;
const WARM_MIN = 35;

const URGENT = /\b(asap|urgent|immediately|right away|this week|next week)\b/i;
const MEDIUM = /\b(this month|next month|2 weeks|two weeks)\b/i;
const INTENT = /\b(need|looking for|hire|quote|proposal|project|build|automate|automation)\b/i;
const NEGATIVE = /\b(free|intern(ship)?|jobs?|vacanc(y|ies)|backlinks?|guest post)\b/i;

// ===== Helper =====
function parseBudgetMax(text) {
  const t = String(text || '')
    .toLowerCase()
    .replace(/,/g, '')
    .replace(/(\d+(?:\.\d+)?)\s*k\b/g, (m, n) => String(Number(n) * 1000));
  const nums = t.match(/\d+(?:\.\d+)?/g);
  if (!nums) return 0;
  return Math.max(...nums.map(Number));
}

// ===== Main =====
return $input.all().map(item => {
  const lead = item.json;
  let score = 0;
  const reasons = [];

  const email = String(lead.email || '').toLowerCase();
  const domain = email.split('@')[1] || '';
  const message = String(lead.message || '');
  const timeline = String(lead.timeline || '');
  const phoneDigits = String(lead.phone || '').replace(/\D/g, '');
  const budgetMax = parseBudgetMax(lead.budget);

  if (domain && !FREE_DOMAINS.includes(domain)) { score += 20; reasons.push('business_email:+20'); }
  if (String(lead.company || '').trim()) { score += 10; reasons.push('company:+10'); }
  if (phoneDigits.length >= 10) { score += 10; reasons.push('phone:+10'); }

  if (budgetMax >= 3000) { score += 25; reasons.push('budget_high:+25'); }
  else if (budgetMax >= 1000) { score += 15; reasons.push('budget_mid:+15'); }
  else if (budgetMax > 0) { score += 5; reasons.push('budget_low:+5'); }

  if (URGENT.test(timeline)) { score += 20; reasons.push('timeline_urgent:+20'); }
  else if (MEDIUM.test(timeline)) { score += 10; reasons.push('timeline_medium:+10'); }

  if (INTENT.test(message)) { score += 10; reasons.push('intent_words:+10'); }
  if (message.length >= 80) { score += 5; reasons.push('detailed_message:+5'); }
  if (message.length < 20) { score -= 15; reasons.push('short_message:-15'); }
  if (NEGATIVE.test(message)) { score -= 20; reasons.push('spam_words:-20'); }

  score = Math.max(0, Math.min(100, score));
  const category = score >= HOT_MIN ? 'hot' : score >= WARM_MIN ? 'warm' : 'cold';

  return {
    json: {
      ...lead,
      rule_score: score,
      rule_category: category,
      score_breakdown: reasons.join('; ')
    }
  };
});

const lead = $json;

// সাধারণ injection-এর ধরন (সব ধরবে না, তাই এটা একমাত্র সুরক্ষা নয়)
const INJECTION = /(ignore (all |any )?(previous|prior|above) (instructions|prompts?)|system prompt|you are now|disregard .{0,30}instructions|(mark|classify|rate) (this|me|it) as (a )?hot|act as)/i;

const raw = String(lead.message || '');

return {
  json: {
    ...lead,
    message_safe: raw.replace(/[<>]/g, '').slice(0, 1500),
    injection_suspected: INJECTION.test(raw)
  }
};

