const base = $('Prepare AI Input').item.json;
const ai = $json.output; // AI ব্যর্থ হলে undefined হতে পারে

const CATEGORIES = ['hot', 'warm', 'cold'];
const RANK = { cold: 0, warm: 1, hot: 2 };
const CONF_MIN = 0.6;

// helper field গুলো sheet-এ যাবে না
const { message_safe, injection_suspected, ...lead } = base;

// ১) AI output যাচাই
const valid =
  ai && typeof ai === 'object' &&
  CATEGORIES.includes(ai.category) &&
  typeof ai.confidence === 'number' && ai.confidence >= 0 && ai.confidence <= 1 &&
  typeof ai.reason === 'string' && ai.reason.trim().length > 0;

let finalCategory;
let status = 'new';
let reviewReason = '';
let lastError = '';

if (!valid) {
  // ২) AI ব্যর্থ বা অবৈধ → rule category-তে fallback + manual review
  finalCategory = lead.rule_category;
  status = 'needs_review';
  reviewReason = 'AI output missing or invalid';
  lastError = 'AI classification failed; used rule-based category';
} else if (injection_suspected) {
  // ৩) Injection সন্দেহ → AI-কে বিশ্বাস না করে rule category
  finalCategory = lead.rule_category;
  status = 'needs_review';
  reviewReason = 'Possible prompt injection in message';
} else {
  const gap = Math.abs(RANK[ai.category] - RANK[lead.rule_category]);
  if (gap >= 2) {
    // ৪) hot ↔ cold মতভেদ → মানুষ দেখবে
    finalCategory = lead.rule_category;
    status = 'needs_review';
    reviewReason = `AI (${ai.category}) and rules (${lead.rule_category}) strongly disagree`;
  } else if (ai.confidence < CONF_MIN) {
    // ৫) কম আত্মবিশ্বাস
    finalCategory = lead.rule_category;
    status = 'needs_review';
    reviewReason = `Low AI confidence (${ai.confidence})`;
  } else {
    finalCategory = ai.category;
  }
}

return {
  json: {
    ...lead,
    ai_category: valid ? ai.category : 'error',
    ai_confidence: valid ? ai.confidence : '',
    ai_reason: valid ? ai.reason.slice(0, 300) : '',
    next_action: valid && typeof ai.next_action === 'string' ? ai.next_action.slice(0, 200) : '',
    language: valid && ['en', 'bn', 'other'].includes(ai.language) ? ai.language : '',
    final_category: finalCategory,
    status,
    review_reason: reviewReason,
    last_error: lastError
  }
};

// ===== CONFIG (নিজের মান বসান) =====
const AGENCY_NAME = 'MD. MEHEDI HASAN';
const PORTFOLIO_URL = 'https://your-portfolio-link.example';
const SLA_HOT_EN = 'within 1 hour';
const SLA_HOT_BN = '১ ঘণ্টার মধ্যে';

// Save New Lead-এর output-এর উপর নির্ভর না করে আগের node থেকে data নিচ্ছি
const lead = $('Validate & Decide').item.json;

const clean = (v) => String(v ?? '').replace(/[<>\r\n]/g, ' ').trim();
const firstName = clean(lead.name).split(/\s+/)[0] || 'there';
const lang = lead.language === 'bn' ? 'bn' : 'en';
const cat = lead.final_category;

// ===== Customer reply (static template, AI-র লেখা নয়) =====
const T = {
  en: {
    hot: {
      subject: `We received your request - ${AGENCY_NAME}`,
      body: `Hi ${firstName},\n\nThank you for contacting ${AGENCY_NAME}. We have received your request and a member of our team will contact you ${SLA_HOT_EN}.\n\nBest regards,\n${AGENCY_NAME}`
    },
    warm: {
      subject: `Thanks for reaching out - ${AGENCY_NAME}`,
      body: `Hi ${firstName},\n\nThank you for your interest in ${AGENCY_NAME}. We will review your request and reply within 1 business day.\n\nIn the meantime, you can see our work here: ${PORTFOLIO_URL}\n\nBest regards,\n${AGENCY_NAME}`
    },
    cold: {
      subject: `We received your message - ${AGENCY_NAME}`,
      body: `Hi ${firstName},\n\nThank you for contacting ${AGENCY_NAME}. We have received your message and will get back to you within 2-3 business days.\n\nBest regards,\n${AGENCY_NAME}`
    }
  },
  bn: {
    hot: {
      subject: `আপনার অনুরোধ পেয়েছি - ${AGENCY_NAME}`,
      body: `প্রিয় ${firstName},\n\n${AGENCY_NAME}-এর সঙ্গে যোগাযোগ করার জন্য ধন্যবাদ। আপনার অনুরোধ আমরা পেয়েছি এবং আমাদের একজন প্রতিনিধি ${SLA_HOT_BN} আপনার সঙ্গে যোগাযোগ করবেন।\n\nশুভেচ্ছান্তে,\n${AGENCY_NAME}`
    },
    warm: {
      subject: `যোগাযোগের জন্য ধন্যবাদ - ${AGENCY_NAME}`,
      body: `প্রিয় ${firstName},\n\n${AGENCY_NAME}-এ আগ্রহ দেখানোর জন্য ধন্যবাদ। আমরা আপনার অনুরোধ দেখে ১ কার্যদিবসের মধ্যে উত্তর দেব।\n\nইতিমধ্যে আমাদের কাজ দেখতে পারেন: ${PORTFOLIO_URL}\n\nশুভেচ্ছান্তে,\n${AGENCY_NAME}`
    },
    cold: {
      subject: `আপনার বার্তা পেয়েছি - ${AGENCY_NAME}`,
      body: `প্রিয় ${firstName},\n\n${AGENCY_NAME}-এর সঙ্গে যোগাযোগ করার জন্য ধন্যবাদ। আপনার বার্তা পেয়েছি, ২-৩ কার্যদিবসের মধ্যে উত্তর দেব।\n\nশুভেচ্ছান্তে,\n${AGENCY_NAME}`
    }
  }
};

const tpl = (T[lang] && T[lang][cat]) ? T[lang][cat] : { subject: '', body: '' };

// ===== Team alert (plain text) =====
const icon = lead.status === 'needs_review' ? '⚠️ NEEDS REVIEW'
  : cat === 'hot' ? '🔥 HOT LEAD'
  : cat === 'warm' ? '🟡 WARM LEAD'
  : '⚪ COLD LEAD';

const alertText = [
  icon,
  lead.review_reason ? `Reason: ${clean(lead.review_reason)}` : null,
  `Name: ${clean(lead.name)}`,
  `Company: ${clean(lead.company) || '-'}`,
  `Email: ${clean(lead.email)}`,
  `Phone: ${clean(lead.phone) || '-'}`,
  `Budget: ${clean(lead.budget) || '-'} | Timeline: ${clean(lead.timeline) || '-'}`,
  `Score: rule ${lead.rule_score} (${lead.rule_category}) | AI ${lead.ai_category} (${lead.ai_confidence})`,
  `Why: ${clean(lead.ai_reason) || '-'}`,
  `Next: ${clean(lead.next_action) || '-'}`,
  `Message: ${clean(lead.message).slice(0, 300)}`,
  `Lead ID: ${lead.lead_id}`
].filter(Boolean).join('\n');

return {
  json: {
    lead_id: lead.lead_id,
    email: lead.email,
    final_category: cat,
    status: lead.status,
    language: lang,
    reply_subject: tpl.subject,
    reply_body: tpl.body,
    alert_text: alertText
  }
};
